<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
import { COLLAB_STAGES, decideCollabSubmission, getCollabArtifacts, getCollabProject, getCollabTaskPrompt, getCollabWorkflow, type CollabArtifact, type CollabMember, type CollabProject, type CollabStage, type CollabSubmission } from '../api/collab-projects.api'
const route=useRoute();const router=useRouter();const auth=useAuthStore();const projectKey=computed(()=>String(route.params.projectKey));const stageKey=computed(()=>String(route.params.stageKey));const project=ref<CollabProject|null>(null);const stage=ref<CollabStage|null>(null);const artifacts=ref<CollabArtifact[]>([]);const members=ref<CollabMember[]>([]);const loading=ref(true);const busy=ref(false);const error=ref('');const rejectComment=ref('');const prompt=ref('');const showPrompt=ref(false)
const stageDef=computed(()=>COLLAB_STAGES.find(s=>s.key===stageKey.value));const currentSubmission=computed<CollabSubmission|null>(()=>{const pending=(s?:string|null)=>['PENDING_APPROVAL','PENDING'].includes(s||'');const candidate=stage.value?.submission||stage.value?.submissions?.find(s=>pending(s.state||s.status));if(candidate&&pending(candidate.state||candidate.status||stage.value?.submissionStatus))return candidate;if(stage.value?.submissionId&&pending(stage.value.submissionStatus))return{submissionId:stage.value.submissionId,state:stage.value.submissionStatus||undefined,artifactVersionId:stage.value.artifactVersionId??0,approvalVersionNo:stage.value.approvalVersionNo??0,reviewerUserId:stage.value.frozenReviewerUserId??stage.value.reviewerUserId,approvalState:stage.value.approvalState};return null});const currentSubmissionArtifact=computed(()=>artifacts.value.find(a=>a.artifactVersionId===currentSubmission.value?.artifactVersionId))
const contextPrompt=ref('')
const isStageOwner=computed(()=>auth.user?.id===stage.value?.ownerUserId);const canSubmitStage=computed(()=>{const order=stage.value?.stageOrder??stage.value?.order;const current=project.value?.currentStageOrder;const inCurrentGroup=order===current||((current===3||current===5)&&order===current+1);return isStageOwner.value&&Boolean(stage.value)&&inCurrentGroup&&['WAITING','READY','IN_PROGRESS'].includes(stage.value?.status||'')});const isReviewer=computed(()=>auth.user?.id===(currentSubmission.value?.reviewerUserId??stage.value?.reviewerUserId));const canReview=computed(()=>isReviewer.value&&(!currentSubmission.value?.approvalState||currentSubmission.value.approvalState==='PENDING'))
function msg(e:unknown){return(e as {response?:{data?:{message?:string}}})?.response?.data?.message||(e as Error)?.message||'操作失败'}function textStatus(v:string){return({NOT_STARTED:'未开始',WAITING:'待开始',READY:'待开始',IN_PROGRESS:'进行中',REWORK:'退回重做',PENDING_APPROVAL:'待审批',COMPLETED:'已完成',REJECTED:'已驳回'}as Record<string,string>)[v]||v}
async function load(){loading.value=true;error.value='';try{const[p,w,a]=await Promise.all([getCollabProject(projectKey.value),getCollabWorkflow(projectKey.value),getCollabArtifacts(projectKey.value)]);project.value=p;stage.value=w.stages.find(s=>s.stageKey===stageKey.value)||null;artifacts.value=a;members.value=p.members || [];if(!stage.value)error.value='项目中没有这个阶段'}catch(e){error.value=msg(e)}finally{loading.value=false}}
async function decide(decision:'APPROVE'|'REJECT'){if(!currentSubmission.value)return;if(decision==='REJECT'&&!rejectComment.value.trim()){error.value='驳回时请填写原因';return}busy.value=true;error.value='';try{await decideCollabSubmission(projectKey.value,currentSubmission.value.submissionId??currentSubmission.value.id??0,{decision,comment:rejectComment.value.trim(),expectedVersion:currentSubmission.value.approvalVersionNo??stage.value?.approvalVersionNo??0});rejectComment.value='';await load()}catch(e){error.value=msg(e)}finally{busy.value=false}}
async function loadPrompt(){busy.value=true;try{const result=await getCollabTaskPrompt(projectKey.value,stageKey.value);prompt.value=result.prompt;contextPrompt.value=result.contextPrompt||'';showPrompt.value=true}catch(e){error.value=msg(e)}finally{busy.value=false}}
async function copyPrompt(text=prompt.value){await navigator.clipboard.writeText(text);window.alert('阶段任务提示词已复制')}
function memberName(id?:number|null){return members.value.find(m=>m.userId===id)?.displayName||'—'}function reviewerNames(){return [stage.value?.reviewerUserId,...(stage.value?.additionalReviewerUserIds||[])].filter((id):id is number=>id!=null).map(memberName).join('、')||'—'}
onMounted(load)
</script>

<template><main class="collab-page"><button class="back-link" @click="router.push({name:'collab-project-detail',params:{projectKey}})">← {{project?.name||'项目概览'}}</button><div v-if="error" class="notice">{{error}} <button @click="error=''">关闭</button></div><div v-if="loading" class="empty">正在加载阶段…</div><template v-else-if="stage"><header class="stage-head"><div><span class="kicker">STAGE {{String(stage.stageOrder||stage.order||0).padStart(2,'0')}} / 08</span><h1>{{stage.title||stageDef?.title||stage.stageKey}}</h1><p>{{stageDef?.git?'交付 Markdown 阶段报告，并附仓库及 commit 或 PR 证据。':'提交符合阶段模板的 Markdown 产物。'}}</p></div><button class="secondary" :disabled="busy" @click="loadPrompt">查看本地 Agent 工作提示词</button></header>
 <div class="stage-layout"><div class="main-col"><section class="panel"><div class="panel-heading"><div><h2>当前状态</h2><span class="status-pill">{{textStatus(stage.status)}}</span></div><span class="round-label">第 {{stage.attemptNo}} 轮 · 版本 {{stage.versionNo}}</span></div><div class="assignment-box"><div><small>阶段负责人</small><strong>{{stage.ownerName||memberName(stage.ownerUserId)}}</strong></div><div><small>审批人</small><strong>{{reviewerNames()}}</strong></div><div><small>产物类型</small><strong>{{stage.artifactKind||stageDef?.kind}}</strong></div></div></section>
  <section v-if="stage.status==='REWORK' || stage.status==='REJECTED'" class="panel access-note"><h2>本阶段已驳回</h2><p>请根据审批意见修改本地文档，再使用右侧阶段提示词调用 <code>project-artifact-submit</code> Skill 重新上传。提交提示词中的 <code>{local file}</code> 需要替换成本机产物路径。</p></section><section v-else-if="canSubmitStage" class="panel access-note"><h2>阶段产物统一通过本地 Agent 提交</h2><p>请使用右侧与飞书阶段卡片一致的提示词，调用 <code>project-artifact-submit</code> Skill 上传产物；提交提示词中的 <code>{local file}</code> 需要替换成本机产物路径。<template v-if="stageDef?.git">开发阶段还需在本地 Agent 提示词中提供仓库及 Commit 或 PR 证据。</template></p></section><section v-else class="panel access-note">{{stage.status==='COMPLETED'?'本阶段已完成，产物不可修改。':currentSubmission?'产物已提交，等待审批处理。':'产物提交仅限当前阶段的指定负责人。'}}</section>
  <section v-if="currentSubmission" class="panel review-panel"><header class="section-head"><div><h2>待处理审批</h2><p>提交 {{currentSubmission.submissionId||currentSubmission.id}} · {{currentSubmission.reviewerName||memberName(currentSubmission.reviewerUserId)}}</p></div><span class="pending">{{currentSubmission.approvalMode==='MANUAL'?'等待人工审批':'自动处理'}}</span></header><div class="review-artifact-link"><a v-if="currentSubmissionArtifact?.feishuUrl" class="feishu-link" :href="currentSubmissionArtifact?.feishuUrl" target="_blank" rel="noopener noreferrer">在飞书中查看待审批产物 →</a><p v-else>产物正在发布到飞书；发布完成后可从右侧打开，本页面不展示正文。</p><div v-if="currentSubmissionArtifact?.repositoryUrl || currentSubmissionArtifact?.commitOrPullRequestUrl" class="git-evidence"><strong>代码链接</strong><a v-if="currentSubmissionArtifact.repositoryUrl" :href="currentSubmissionArtifact.repositoryUrl" target="_blank" rel="noopener noreferrer">Git 仓库 ↗</a><a v-if="currentSubmissionArtifact.commitOrPullRequestUrl" :href="currentSubmissionArtifact.commitOrPullRequestUrl" target="_blank" rel="noopener noreferrer">Commit / PR ↗</a></div></div><template v-if="canReview"><label class="field">审批意见<textarea v-model="rejectComment" rows="2" placeholder="驳回时必须填写原因；批准时可选填写" /></label><div class="form-actions"><button class="secondary" :disabled="busy" @click="decide('REJECT')">驳回并退回重做</button><button class="primary" :disabled="busy" @click="decide('APPROVE')">批准并推进</button></div></template><p v-else class="review-readonly">{{isReviewer && currentSubmission.approvalState==='APPROVED'?'你已完成审批，正在等待其他审批人。':'审批操作仅限当前指定审批人。'}}</p></section></div>
 <aside class="side-col"><section class="panel"><template v-if="currentSubmission"><h2>待审批产物</h2><p class="sub">产物正文不在此页面展示</p><div v-if="currentSubmissionArtifact?.feishuUrl" class="artifact"><span class="file-mark">↗</span><div><strong>{{currentSubmissionArtifact.title}}</strong><a class="feishu-link" :href="currentSubmissionArtifact.feishuUrl" target="_blank" rel="noopener noreferrer">在飞书中查看 →</a></div></div><p v-else class="empty-small">产物正在发布到飞书；发布完成后可在此处查看链接。 <button class="refresh-link" :disabled="loading" @click="load">刷新</button></p><div v-if="currentSubmissionArtifact?.repositoryUrl || currentSubmissionArtifact?.commitOrPullRequestUrl" class="git-evidence"><strong>代码链接</strong><a v-if="currentSubmissionArtifact.repositoryUrl" :href="currentSubmissionArtifact.repositoryUrl" target="_blank" rel="noopener noreferrer">Git 仓库 ↗</a><a v-if="currentSubmissionArtifact.commitOrPullRequestUrl" :href="currentSubmissionArtifact.commitOrPullRequestUrl" target="_blank" rel="noopener noreferrer">Commit / PR ↗</a></div></template><template v-else-if="stage.status==='COMPLETED'"><h2>阶段文档</h2><p class="sub">已完成阶段的产物请通过飞书查看</p><div v-if="!artifacts.filter(a=>a.stageKey===stageKey).length" class="empty-small">没有已批准产物</div><div v-for="a in artifacts.filter(x=>x.stageKey===stageKey)" :key="a.artifactVersionId" class="artifact"><span class="file-mark">MD</span><div><strong>{{a.title}}</strong><small>v{{a.versionNo}} · 第 {{a.attemptNo}} 轮</small><a v-if="a.feishuUrl" class="feishu-link" :href="a.feishuUrl" target="_blank" rel="noopener noreferrer">在飞书中查看 →</a><small v-else class="publish-pending">飞书文档尚未发布</small></div></div></template><template v-else><h2>通过的产物</h2><p class="sub">当前项目成员可见的正式文档</p><div v-if="!artifacts.filter(a=>a.stageKey===stageKey).length" class="empty-small">这个阶段还没有已批准产物</div><article v-for="a in artifacts.filter(x=>x.stageKey===stageKey&&!x.pendingApproval)" :key="a.artifactVersionId" class="artifact"><span class="file-mark">MD</span><div><strong>{{a.title}}</strong><small>v{{a.versionNo}} · 第 {{a.attemptNo}} 轮</small></div></article></template></section><section class="panel"><h2>本地 Agent 提示词</h2><p class="sub">与飞书阶段卡片保持一致；提交前请替换本机产物地址占位符。</p><button class="secondary wide" @click="loadPrompt">查看阶段提示词</button></section><button class="history-link" @click="router.push({name:'collab-project-history',params:{projectKey}})">查看项目审批与事件历史 →</button></aside></div></template>
 <div v-if="showPrompt" class="prompt-overlay" @click.self="showPrompt=false"><section><button class="close" @click="showPrompt=false">×</button><span class="kicker">LOCAL AGENT PROMPT</span><h2>阶段工作提示词</h2><template v-if="contextPrompt"><h3>获取前序阶段产物提示词</h3><pre>{{contextPrompt}}</pre><button class="secondary" @click="copyPrompt(contextPrompt)">复制获取提示词</button></template><h3>阶段完成后推送提示词</h3><pre>{{prompt}}</pre><p class="prompt-note">请先将 <code>{local file}</code> 替换为产物在本机上的实际文件路径。</p><button class="primary" @click="copyPrompt(prompt)">复制提交提示词</button></section></div>
 </main></template>

<style scoped>
.collab-page{max-width:1240px;margin:auto;padding:29px 42px 70px;color:var(--text-1)}
.back-link,.history-link{border:0;background:none;color:var(--text-2);padding:0 0 21px;cursor:pointer}
.back-link:hover,.history-link:hover{color:var(--accent-300)}
.feishu-link{display:inline-block;margin-top:5px;color:var(--accent-300);font-size:12px;text-decoration:none}.feishu-link:hover{text-decoration:underline}.publish-pending{color:var(--text-3)}
.stage-head{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin-bottom:21px}
.kicker{font:700 10px var(--font-mono);letter-spacing:.16em;color:var(--accent-400)}
.stage-head h1{font-size:29px;letter-spacing:-.04em;margin:8px 0}
.stage-head p,.section-head p,.sub{font-size:12px;color:var(--text-2);margin:0}
.primary,.secondary{border:0;border-radius:var(--radius-sm);padding:10px 14px;font-weight:650;cursor:pointer;transition:box-shadow var(--duration-fast)}
.primary{background:linear-gradient(135deg,var(--accent-500),var(--accent-600));color:var(--text-on-accent);box-shadow:var(--shadow-accent)}
.primary:disabled{opacity:.5;cursor:not-allowed}
.secondary{background:var(--surface-3);color:var(--text-1)}
.stage-layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(260px,.7fr);gap:16px}
.panel{background:var(--surface-1);border:1px solid var(--border-1);border-radius:var(--radius-md);padding:17px;margin-bottom:14px;box-shadow:var(--inner-highlight)}
.panel h2,.section-head h2{font-size:15px;margin:0 0 5px;color:var(--text-1)}
.panel-heading,.section-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}
.status-pill,.pending{font-size:11px;padding:5px 8px;background:var(--accent-soft);border-radius:var(--radius-xs);color:var(--accent-300)}
.round-label{font-size:11px;color:var(--text-3)}
.assignment-box{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:13px;border-radius:var(--radius-sm);background:var(--surface-2)}
.assignment-box div{display:grid;gap:6px}
.assignment-box small,.field small{font-size:10px;color:var(--text-3)}
.assignment-box strong{font-size:12px;color:var(--text-1)}
.field{display:grid;gap:7px;margin:12px 0;color:var(--text-2);font-size:12px;font-weight:650}
.field input,.field textarea{width:100%;box-sizing:border-box;background:var(--surface-2);border:1px solid var(--border-2);border-radius:var(--radius-sm);padding:10px;color:var(--text-1);font:13px/1.55 inherit}
.field input:focus,.field textarea:focus{outline:none;border-color:var(--border-accent);box-shadow:0 0 0 3px var(--accent-glow)}
.field textarea{resize:vertical;font-family:var(--font-mono)}
.field input::placeholder,.field textarea::placeholder{color:var(--text-4)}
.link-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.form-actions{display:flex;align-items:center;gap:11px;margin-top:13px}
.form-actions span{font-size:10px;color:var(--text-3)}
.refresh-link{border:0;background:none;color:var(--accent-300);cursor:pointer}.review-artifact-link{padding:12px 0;color:var(--text-2);font-size:12px}.review-artifact-link p{margin:0}.git-evidence{display:flex;flex-wrap:wrap;gap:10px 16px;margin-top:12px;padding-top:10px;border-top:1px solid var(--border);font-size:12px}.git-evidence strong{width:100%;color:var(--text-2)}.git-evidence a{color:var(--accent-300);text-decoration:none}.git-evidence a:hover{text-decoration:underline}.prompt-note{font-size:12px;color:var(--text-2)}.prompt-overlay h3{font-size:13px;color:var(--text-1);margin:16px 0 8px}
.side-col h2{font-size:15px;margin:0 0 6px;color:var(--text-1)}
.empty-small{font-size:11px;color:var(--text-3);padding:14px 0}
.artifact{display:flex;align-items:center;gap:9px;border-top:1px solid var(--border-1);padding:10px 0}
.file-mark{display:grid;place-items:center;width:29px;height:31px;background:var(--accent-soft);color:var(--accent-300);border-radius:var(--radius-xs);font:9px var(--font-mono)}
.artifact div{display:grid;gap:4px}
.artifact strong{font-size:11px;color:var(--text-1)}
.artifact small{font-size:10px;color:var(--text-3)}
.wide{width:100%;margin-top:13px}
.history-link{padding-top:4px;font-size:12px}
.notice{background:var(--error-soft);color:var(--error);border:1px solid rgb(248 113 113 / 35%);padding:10px;border-radius:var(--radius-sm);margin-bottom:12px}
.notice button{float:right;border:0;background:none;color:inherit;cursor:pointer}
.empty{padding:70px;text-align:center;color:var(--text-2)}
.access-note,.review-readonly{color:var(--text-2);font-size:12px}
.prompt-overlay{position:fixed;inset:0;background:var(--mask-bg);display:grid;place-items:center;padding:20px;z-index:120}
.prompt-overlay section{position:relative;width:min(720px,100%);background:var(--surface-overlay-solid);border:1px solid var(--border-2);padding:24px;border-radius:var(--radius-lg);box-shadow:var(--shadow-xl)}
.prompt-overlay h2{margin:8px 0 14px;color:var(--text-1)}
.prompt-overlay pre{max-height:55vh;overflow:auto;white-space:pre-wrap;background:var(--surface-2);border:1px solid var(--border-1);border-radius:var(--radius-sm);padding:15px;font:12px/1.6 var(--font-mono);color:var(--text-2)}
.close{position:absolute;right:14px;top:12px;border:0;background:none;color:var(--text-2);font-size:23px;cursor:pointer}
@media(max-width:850px){.collab-page{padding:24px 15px}.stage-layout{grid-template-columns:1fr}.stage-head{align-items:flex-start;flex-direction:column}.link-fields{grid-template-columns:1fr}.assignment-box{grid-template-columns:1fr 1fr}}
</style>
